{
  "formular": "Austrittsmeldung (Nachbildung nach Vorbild SWICA)",
  "felder": [
    {
      "feld": "Nachname",
      "vorgabe": "Der Nachname der versicherten Person muss vollständig und korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Vorname",
      "vorgabe": "Der Vorname der versicherten Person muss vollständig und korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Geburtsdatum",
      "vorgabe": "Das exakte Geburtsdatum (TT.MM.JJJJ) muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Nationalität",
      "vorgabe": "Die Nationalität der versicherten Person muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Versichert-en-Nr.",
      "vorgabe": "Die eindeutige Versichertennummer der Person muss korrekt eingetragen werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Aufenthaltsbewilligung",
      "vorgabe": "Falls vorhanden, muss die gültige Aufenthaltsbewilligung (Typ und Nummer) angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Beruf",
      "vorgabe": "Der aktuelle oder zuletzt ausgeübte Beruf muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Strasse/Nr.",
      "vorgabe": "Die vollständige Strassenadresse inklusive Hausnummer muss korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "PLZ",
      "vorgabe": "Die korrekte Postleitzahl des Wohnorts muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Wohnort",
      "vorgabe": "Der vollständige Wohnort (Ortschaft) muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Telefon",
      "vorgabe": "Eine gültige Telefonnummer für Rückfragen muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "E-Mail",
      "vorgabe": "Eine gültige E-Mail-Adresse muss angegeben werden, falls eine Kommunikation per E-Mail gewünscht ist.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Geschichte (männlich/weiblich)",
      "vorgabe": "Das Geschlecht der versicherten Person muss angekreuzt werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Erklärung der versicherten Person (Austrittsstatus)",
      "vorgabe": "Es muss eindeutig angegeben werden, ob die Person bereits ausgetreten ist oder den Austritt plant.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Austrittsdatum",
      "vorgabe": "Das genaue Datum des Austritts aus der Firma muss angegeben werden (TT.MM.JJJJ).",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Interesse an Weiterführung",
      "vorgabe": "Es muss angekreuzt werden, ob eine unverbindliche Offerte für die Weiterführung der Versicherung gewünscht wird oder ob auf das Recht verzichtet wird.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Unterschrift",
      "vorgabe": "Die eigenhändige Unterschrift der versicherten Person muss vorhanden sein.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Datum",
      "vorgabe": "Das Datum der Unterzeichnung muss korrekt eingetragen werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    }
  ]
}
